// Kategori ikonları
const categoryIcons = {
  "Sponsorluk": <Award size={16} />,
  "Yarışma": <TrendingUp size={16} />,
  "Teknik": <Tag size={16} />,
  "Eğitim": <Calendar size={16} />,
  "default": <Tag size={16} />
};

// View types for the announcements
const VIEW_TYPES = {
  GRID: 'grid',
  LIST: 'list',
  TIMELINE: 'timeline'
};

// Sort types for the announcements
const SORT_TYPES = {
  DATE_DESC: 'date_desc',
  DATE_ASC: 'date_asc',
  POPULAR: 'popular'
};

const ModernDuyurularPage = () => {
  // States
  const [announcements, setAnnouncements] = useState(announcementData);
  const [activeCategory, setActiveCategory] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [featuredAnnouncement, setFeaturedAnnouncement] = useState(null);
  const [viewType, setViewType] = useState(VIEW_TYPES.GRID);
  const [sortType, setSortType] = useState(SORT_TYPES.DATE_DESC);
  const [isLoading, setIsLoading] = useState(true);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isFilterMenuOpen, setIsFilterMenuOpen] = useState(false);
  const [isNavSticky, setIsNavSticky] = useState(false);
  
  // Refs
  const filterRef = useRef(null);
  const navRef = useRef(null);
  
  // Effect for loading simulation
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 800);
    
    return () => clearTimeout(timer);
  }, []);
  
  // Featured announcement effect
  useEffect(() => {
    const featured = announcementData.filter(item => item.featured);
    if (featured.length > 0) {
      // Sort by importance if multiple are featured
      const sortedFeatured = [...featured].sort((a, b) => b.importance - a.importance);
      setFeaturedAnnouncement(sortedFeatured[0]);
    }
  }, []);
  
  // Sticky nav effect
  useEffect(() => {
    const handleScroll = () => {
      if (navRef.current) {
        setIsNavSticky(window.scrollY > navRef.current.offsetTop);
      }
    };
    
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);
  
  // Close filter menu when clicked outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (filterRef.current && !filterRef.current.contains(event.target)) {
        setIsFilterMenuOpen(false);
      }
    };
    
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);
  
  // Ripple effect for buttons
  const createRipple = (event) => {
    const button = event.currentTarget;
    const ripple = document.createElement('span');
    
    const diameter = Math.max(button.clientWidth, button.clientHeight);
    const radius = diameter / 2;
    
    ripple.style.width = ripple.style.height = `${diameter}px`;
    ripple.style.left = `${event.clientX - button.getBoundingClientRect().left - radius}px`;
    ripple.style.top = `${event.clientY - button.getBoundingClientRect().top - radius}px`;
    ripple.classList.add('ripple');
    
    const existingRipple = button.querySelector('.ripple');
    if (existingRipple) {
      existingRipple.remove();
    }
    
    button.appendChild(ripple);
    
    setTimeout(() => {
      ripple.remove();
    }, 600);
  };
  
  // Filter announcements
  const filteredAnnouncements = announcements
    .filter(announcement => {
      // Search filter
      const matchesSearch = searchTerm === '' || 
        announcement.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
        announcement.content.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (announcement.tags && announcement.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase())));
      
      // Category filter
      const matchesCategory = activeCategory === 'all' || announcement.category === activeCategory;
      
      return matchesSearch && matchesCategory;
    })
    .sort((a, b) => {
      // Apply sorting
      switch(sortType) {
        case SORT_TYPES.DATE_ASC:
          return new Date(a.date) - new Date(b.date);
        case SORT_TYPES.POPULAR:
          return b.likes - a.likes;
        case SORT_TYPES.DATE_DESC:
        default:
          return new Date(b.date) - new Date(a.date);
      }
    });
  
  // Category change handler
  const handleCategoryChange = (category) => {
    setActiveCategory(category);
    // Add animation for change
    const filters = document.querySelector('.category-filters');
    filters.classList.add('fade-in');
    setTimeout(() => {
      filters.classList.remove('fade-in');
    }, 500);
  };
  
  // Search handler with debounce
  const debounce = (func, delay) => {
    let timeoutId;
    return function(...args) {
      clearTimeout(timeoutId);
      timeoutId = setTimeout(() => {
        func.apply(this, args);
      }, delay);
    };
  };
  
  const handleSearchChange = debounce((value) => {
    setSearchTerm(value);
  }, 300);
  
  // Navigation to announcement detail
  const navigateToAnnouncementDetail = useCallback((id) => {
    // In a real app, navigate to detail page
    // For now, show modal or alert
    alert(`Duyuru #${id} detayları görüntülenecek\nBu özellik geliştirilme aşamasında.`);
  }, []);
  
  // Like functionality
  const handleLike = (id) => {
    setAnnouncements(prev => 
      prev.map(item => 
        item.id === id 
          ? {...item, likes: item.likes + 1}
          : item
      )
    );
  };
  
  // Share functionality
  const handleShare = (announcement) => {
    if (navigator.share) {
      navigator.share({
        title: announcement.title,
        text: announcement.excerpt,
        url: window.location.href
      }).catch(err => {
        console.error('Paylaşım hatası:', err);
      });
    } else {
      // Fallback for browsers without Web Share API
      const shareText = `${announcement.title}\n${announcement.excerpt}\n${window.location.href}`;
      navigator.clipboard.writeText(shareText)
        .then(() => alert('Duyuru linki panoya kopyalandı!'))
        .catch(err => {
          console.error('Kopyalama hatası:', err);
          alert('Paylaşım hatası oluştu.');
        });
    }
  };
  
  // Toggle dark mode
  const toggleDarkMode = () => {
    setIsDarkMode(!isDarkMode);
    document.body.classList.toggle('dark-mode-enabled');
  };
  
  // Modern announcement card component
  const AnnouncementCard = ({ announcement }) => {
    const categoryStyle = categoryColors[announcement.category] || categoryColors.default;
    const categoryIcon = categoryIcons[announcement.category] || categoryIcons.default;
    
    return (
      <motion.div 
        className="announcement-card fancy-hover"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4 }}
        whileHover={{ y: -8 }}
      >
        <div className="card-content">
          {/* Category and date */}
          <div className="flex justify-between items-center mb-4">
            <div className={`category-tag ${categoryStyle.bg} ${categoryStyle.text} ${categoryStyle.border}`}>
              <span className={`mr-1.5 ${categoryStyle.icon}`}>{categoryIcon}</span>
              {announcement.category}
            </div>
            <div className="text-gray-500 text-xs flex items-center">
              <Clock size={14} className="mr-1.5" />
              {announcement.date}
            </div>
          </div>
          
          {/* Title */}
          <h3 className="text-xl font-semibold text-gray-800 mb-3 hover:text-voltaris-red transition-colors line-clamp-2">
            {announcement.title}
          </h3>
          
          {/* Excerpt */}
          <p className="text-gray-600 text-sm mb-4 flex-grow line-clamp-3">
            {announcement.excerpt}
          </p>
          
          {/* Tags */}
          {announcement.tags && announcement.tags.length > 0 && (
            <div className="flex flex-wrap gap-2 my-3">
              {announcement.tags.map((tag, index) => (
                <span 
                  key={index} 
                  className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full hover:bg-gray-200 transition-colors"
                >
                  #{tag}
                </span>
              ))}
            </div>
          )}
        </div>
        
        {/* Card footer */}
        <div className="card-footer">
          <div className="flex items-center gap-2">
            {announcement.location && (
              <div className="flex items-center text-gray-500 text-xs">
                <MapPin size={12} className="mr-1" />
                {announcement.location}
              </div>
            )}
          </div>
          
          <div className="flex items-center gap-3">
            <button 
              onClick={() => handleLike(announcement.id)} 
              className="text-gray-500 hover:text-voltaris-red flex items-center text-xs transition-colors"
            >
              <ThumbsUp size={14} className="mr-1" />{announcement.likes}
            </button>
            
            <button 
              onClick={() => handleShare(announcement)} 
              className="text-gray-500 hover:text-voltaris-red transition-colors"
            >
              <Share2 size={14} />
            </button>
            
            <button 
              onClick={() => navigateToAnnouncementDetail(announcement.id)}
              className="btn text-voltaris-red text-xs inline-flex items-center hover:text-voltaris-dark-red transition-colors"
              onMouseDown={createRipple}
            >
              Detaylar <ChevronRight size={14} className="ml-1" />
            </button>
          </div>
        </div>
        
        {/* Sponsor logo if exists */}
        {announcement.image && (
          <div className="px-6 py-4 border-t border-gray-100 flex justify-center">
            <img 
              src={`${process.env.PUBLIC_URL}${announcement.image}`}
              alt={announcement.title}
              className="max-h-12 w-auto object-contain opacity-90 hover:opacity-100 transition-opacity"
            />
          </div>
        )}
      </motion.div>
    );
  };
  
  // List view card component (more compact)
  const AnnouncementListItem = ({ announcement }) => {
    const categoryStyle = categoryColors[announcement.category] || categoryColors.default;
    const categoryIcon = categoryIcons[announcement.category] || categoryIcons.default;
    
    return (
      <motion.div 
        className="announcement-card"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.3 }}
      >
        <div className="p-4 flex flex-col md:flex-row md:items-center gap-4">
          <div className="flex-grow">
            <div className="flex items-center mb-2 gap-3">
              <div className={`category-tag ${categoryStyle.bg} ${categoryStyle.text} ${categoryStyle.border}`}>
                <span className={`mr-1.5 ${categoryStyle.icon}`}>{categoryIcon}</span>
                {announcement.category}
              </div>
              <div className="text-gray-500 text-xs flex items-center">
                <Clock size={14} className="mr-1.5" />
                {announcement.date}
              </div>
            </div>
            
            <h3 className="text-lg font-medium text-gray-800 hover:text-voltaris-red transition-colors">
              {announcement.title}
            </h3>
            
            <p className="text-gray-600 text-sm line-clamp-1 md:line-clamp-2 mt-1">
              {announcement.excerpt}
            </p>
          </div>
          
          <div className="flex items-center gap-3 self-end md:self-center">
            <div className="flex items-center text-gray-500 text-xs">
              <ThumbsUp size={12} className="mr-1" />{announcement.likes}
            </div>
            <button 
              onClick={() => navigateToAnnouncementDetail(announcement.id)}
              className="btn btn-primary text-white text-xs px-3 py-1.5 rounded flex items-center"
              onMouseDown={createRipple}
            >
              Detaylar <ChevronRight size={14} className="ml-1" />
            </button>
          </div>
        </div>
      </motion.div>
    );
  };
  
  // Timeline view item
  const TimelineItem = ({ announcement, index }) => {
    const categoryStyle = categoryColors[announcement.category] || categoryColors.default;
    return (
      <motion.div 
        className="timeline-item"
        initial={{ opacity: 0, x: index % 2 === 0 ? 20 : -20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.5, delay: index * 0.1 }}
      >
        <div className="timeline-item-content">
          <div className="text-sm text-gray-500 mb-2">{announcement.date}</div>
          <h3 className="text-lg font-medium text-gray-800 mb-2">{announcement.title}</h3>
          <p className="text-sm text-gray-600 mb-3">{announcement.excerpt}</p>
          
          <div className="flex items-center justify-between mt-3">
            <div className={`text-xs font-medium ${categoryStyle.text}`}>
              {announcement.category}
            </div>
            <button 
              onClick={() => navigateToAnnouncementDetail(announcement.id)}
              className="btn text-voltaris-red text-xs flex items-center"
              onMouseDown={createRipple}
            >
              Detaylar <ChevronRight size={14} className="ml-1" />
            </button>
          </div>
        </div>
      </motion.div>
    );
  };
  
  // Featured announcement component
  const FeaturedAnnouncementCard = ({ announcement }) => {
    if (!announcement) return null;
    
    const categoryStyle = categoryColors[announcement.category] || categoryColors.default;
    
    return (
      <motion.div 
        className="featured-announcement mb-8"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="featured-label">
          <Sparkles size={12} />
          Öne Çıkan
        </div>
        
        <div className="p-6">
          <div className="flex flex-col lg:flex-row gap-6">
            {/* Left content */}
            <div className="lg:w-3/4">
              {/* Categories and date */}
              <div className="flex flex-wrap items-center gap-3 mb-4">
                <div className={`category-tag ${categoryStyle.bg} ${categoryStyle.text} ${categoryStyle.border}`}>
                  {categoryIcons[announcement.category] || categoryIcons.default}
                  <span className="ml-1.5">{announcement.category}</span>
                </div>
                
                <div className="text-gray-500 text-sm flex items-center">
                  <Calendar size={14} className="mr-1.5" />
                  {announcement.date}
                </div>
                
                {announcement.location && (
                  <div className="text-gray-500 text-sm flex items-center">
                    <MapPin size={14} className="mr-1.5" />
                    {announcement.location}
                  </div>
                )}
              </div>
              
              {/* Title */}
              <motion.h2 
                className="text-2xl md:text-3xl font-bold text-gray-800 mb-4"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2, duration: 0.5 }}
              >
                {announcement.title}
              </motion.h2>
              
              {/* Content */}
              <motion.div 
                className="text-gray-600 mb-5 prose prose-sm"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.3, duration: 0.5 }}
                dangerouslySetInnerHTML={{ __html: announcement.content }}
              />
              
              {/* Tags */}
              {announcement.tags && announcement.tags.length > 0 && (
                <div className="flex flex-wrap gap-2 my-4">
                  {announcement.tags.map((tag, index) => (
                    <span 
                      key={index} 
                      className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full hover:bg-gray-200 transition-colors"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              )}
              
              {/* Action buttons */}
              <div className="flex flex-wrap items-center gap-3 mt-6">
                <button 
                  onClick={() => navigateToAnnouncementDetail(announcement.id)}
                  className="btn btn-primary px-5 py-2.5 rounded-md flex items-center font-medium"
                  onMouseDown={createRipple}
                >
                  Detayları Görüntüle <ChevronRight size={16} className="ml-1" />
                </button>
                
                {announcement.website && (
                  <a 
                    href={announcement.website} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="btn btn-secondary px-4 py-2.5 rounded-md flex items-center"
                  >
                    Web Sitesi <ExternalLink size={14} className="ml-2" />
                  </a>
                )}
                
                <button 
                  onClick={() => handleLike(announcement.id)} 
                  className="btn btn-secondary px-3 py-2.5 rounded-md flex items-center"
                >
                  <ThumbsUp size={14} className="mr-1.5" /> {announcement.likes}
                </button>
                
                <button 
                  onClick={() => handleShare(announcement)}
                  className="btn btn-secondary px-3 py-2.5 rounded-md"
                >
                  <Share2 size={14} />
                </button>
              </div>
            </div>
            
            {/* Right side - logo or image */}
            {announcement.image && (
              <div className="lg:w-1/4 flex items-center justify-center">
                <motion.div 
                  className="bg-gray-50 p-6 rounded-lg border border-gray-100"
                  whileHover={{ scale: 1.05, transition: { duration: 0.3 } }}
                >
                  <img 
                    src={`${process.env.PUBLIC_URL}${announcement.image}`}
                    alt={announcement.title}
                    className="max-w-full h-auto object-contain mx-auto"
                  />
                </motion.div>
              </div>
            )}
          </div>
        </div>
      </motion.div>
    );
  };
  
  // Empty state component
  const EmptyState = () => (
    <div className="empty-state-container">
      <div className="empty-animation"></div>
      <h3 className="text-xl font-medium text-gray-700 mt-6">Sonuç Bulunamadı</h3>
      <p className="text-gray-500 mt-2 max-w-md mx-auto">
        Arama kriterlerinize uygun duyuru bulunamadı. Lütfen farklı bir arama terimi deneyin veya filtreleri temizleyin.
      </p>
      <button 
        onClick={() => {setSearchTerm(''); setActiveCategory('all');}}
        className="btn btn-primary mt-4 px-4 py-2 rounded-md"
        onMouseDown={createRipple}
      >
        Tüm Filtreleri Temizle
      </button>
    </div>
  );

  // Main rendering
  return (
    <div className={`duyurular-container ${isDarkMode ? 'dark-mode-enabled' : ''}`}>
      {/* Loading overlay */}
      <AnimatePresence>
        {isLoading && (
          <motion.div 
            className="fixed inset-0 bg-white bg-opacity-80 z-50 flex items-center justify-center"
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.5 }}
          >
            <div className="loading-container">
              <div className="loading-circle"></div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      
      {/* Header */}
      <header className="duyurular-header shadow-sm border-b border-gray-200 py-6 fade-in">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between">
            <h1 className="header-title text-2xl sm:text-3xl font-bold text-gray-800 flex items-center">
              <Calendar size={28} className="mr-3 text-voltaris-red" />
              Duyurular
            </h1>
            <div className="flex items-center gap-3">
              <button 
                onClick={toggleDarkMode}
                className="text-gray-500 hover:text-gray-700 transition-colors"
                title={isDarkMode ? "Aydınlık Moda Geç" : "Karanlık Moda Geç"}
              >
                {isDarkMode ? (
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="12" cy="12" r="5"/>
                    <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>
                  </svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/>
                  </svg>
                )}
              </button>
              <a 
                href="/voltaris/" 
                className="btn btn-secondary flex items-center text-gray-600 hover:text-voltaris-red transition-colors text-sm font-medium px-3 py-2 rounded-md"
              >
                <ArrowLeft size={16} className="mr-1" />
                Ana Sayfaya Dön
              </a>
            </div>
          </div>
        </div>
      </header>
      
      {/* Filter and view options */}
      <div 
        ref={navRef}
        className={`py-4 bg-white border-b border-gray-200 transition-shadow z-10 fade-in ${
          isNavSticky ? 'sticky top-0 shadow-md' : ''
        }`}
      >
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            {/* Category filters for desktop */}
            <div className="hidden md:flex category-filters space-x-2 overflow-x-auto scrollbar-smooth">
              <button 
                onClick={() => handleCategoryChange('all')}
                className={`category-filter-btn px-4 py-2 rounded-md transition-colors ${
                  activeCategory === 'all' 
                    ? 'bg-gray-100 text-gray-800 font-medium active' 
                    : 'text-gray-500 hover:text-gray-800'
                }`}
                onMouseDown={createRipple}
              >
                Tümü
              </button>
              
              {Object.keys(categoryColors).filter(cat => cat !== 'default').map(category => (
                <button 
                  key={category}
                  onClick={() => handleCategoryChange(category)}
                  className={`category-filter-btn px-4 py-2 rounded-md transition-colors ${
                    activeCategory === category 
                      ? `${categoryColors[category].bg} ${categoryColors[category].text} border ${categoryColors[category].border} font-medium active` 
                      : 'text-gray-500 hover:text-gray-800'
                  }`}
                  onMouseDown={createRipple}
                >
                  {category}
                </button>
              ))}
            </div>
            
            {/* Mobile filters dropdown */}
            <div className="relative md:hidden" ref={filterRef}>
              <button 
                onClick={() => setIsFilterMenuOpen(!isFilterMenuOpen)}
                className="btn btn-secondary flex items-center gap-2 px-3 py-2 rounded-md"
                onMouseDown={createRipple}
              >
                <Filter size={16} />
                {activeCategory === 'all' ? 'Kategoriler' : activeCategory}
              </button>
              
              {isFilterMenuOpen && (
                <motion.div 
                  className="absolute top-full left-0 mt-1 bg-white shadow-lg rounded-md border border-gray-200 w-56 py-2 z-20"
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.2 }}
                >
                  <button 
                    onClick={() => {handleCategoryChange('all'); setIsFilterMenuOpen(false);}}
                    className={`w-full text-left px-4 py-2 hover:bg-gray-50 transition-colors ${
                      activeCategory === 'all' ? 'font-medium text-voltaris-red bg-red-50' : ''
                    }`}
                  >
                    Tümü
                  </button>
                  
                  {Object.keys(categoryColors).filter(cat => cat !== 'default').map(category => (
                    <button 
                      key={category}
                      onClick={() => {handleCategoryChange(category); setIsFilterMenuOpen(false);}}
                      className={`w-full text-left px-4 py-2 hover:bg-gray-50 transition-colors ${
                        activeCategory === category 
                          ? `font-medium ${categoryColors[category].text} ${categoryColors[category].bg}`
                          : ''
                      }`}
                    >
                      <span className="flex items-center">
                        <span className={`mr-2 ${categoryColors[category].icon}`}>
                          {categoryIcons[category]}
                        </span>
                        {category}
                      </span>
                    </button>
                  ))}
                </motion.div>
              )}
            </div>
            
            <div className="flex w-full sm:w-auto items-center gap-2">
              {/* Search input */}
              <div className="search-container flex-grow">
                <input
                  type="text"
                  placeholder="Duyurularda ara..."
                  onChange={(e) => handleSearchChange(e.target.value)}
                  className="search-input w-full px-4 py-2 pl-9 border border-gray-300 rounded-md focus:outline-none focus:border-voltaris-red"
                />
                <Search size={16} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500" />
              </div>
              
              {/* Sort dropdown */}
              <div className="relative">
                <button 
                  className="btn btn-secondary px-3 py-2 rounded-md border border-gray-300"
                  onClick={() => document.getElementById('sort-dropdown').classList.toggle('hidden')}
                >
                  <BarChart size={16} />
                </button>
                
                <div 
                  id="sort-dropdown" 
                  className="absolute top-full right-0 mt-1 bg-white shadow-lg rounded-md border border-gray-200 w-48 py-2 z-10 hidden"
                >
                  <button 
                    onClick={() => {
                      setSortType(SORT_TYPES.DATE_DESC);
                      document.getElementById('sort-dropdown').classList.add('hidden');
                    }}
                    className={`w-full text-left px-4 py-2 hover:bg-gray-50 transition-colors ${
                      sortType === SORT_TYPES.DATE_DESC ? 'font-medium text-voltaris-red' : ''
                    }`}
                  >
                    En Yeniler
                  </button>
                  <button 
                    onClick={() => {
                      setSortType(SORT_TYPES.DATE_ASC);
                      document.getElementById('sort-dropdown').classList.add('hidden');
                    }}
                    className={`w-full text-left px-4 py-2 hover:bg-gray-50 transition-colors ${
                      sortType === SORT_TYPES.DATE_ASC ? 'font-medium text-voltaris-red' : ''
                    }`}
                  >
                    En Eskiler
                  </button>
                  <button 
                    onClick={() => {
                      setSortType(SORT_TYPES.POPULAR);
                      document.getElementById('sort-dropdown').classList.add('hidden');
                    }}
                    className={`w-full text-left px-4 py-2 hover:bg-gray-50 transition-colors ${
                      sortType === SORT_TYPES.POPULAR ? 'font-medium text-voltaris-red' : ''
                    }`}
                  >
                    En Çok Beğenilenler
                  </button>
                </div>
              </div>
              
              {/* View toggle */}
              <div className="flex items-center border border-gray-300 rounded-md overflow-hidden">
                <button 
                  className={`px-2 py-2 ${viewType === VIEW_TYPES.GRID ? 'bg-gray-100 text-voltaris-red' : 'bg-white text-gray-500'}`}
                  onClick={() => setViewType(VIEW_TYPES.GRID)}
                  title="Grid View"
                >
                  <Grid size={16} />
                </button>
                <button 
                  className={`px-2 py-2 ${viewType === VIEW_TYPES.LIST ? 'bg-gray-100 text-voltaris-red' : 'bg-white text-gray-500'}`}
                  onClick={() => setViewType(VIEW_TYPES.LIST)}
                  title="List View"
                >
                  <List size={16} />
                </button>
                <button 
                  className={`px-2 py-2 ${viewType === VIEW_TYPES.TIMELINE ? 'bg-gray-100 text-voltaris-red' : 'bg-white text-gray-500'}`}
                  onClick={() => setViewType(VIEW_TYPES.TIMELINE)}
                  title="Timeline View"
                >
                  <Clock size={16} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      
      <main className="container mx-auto px-4 sm:px-6 lg:px-8 py-8 mb-8 fade-in">
        {/* Featured announcement */}
        {featuredAnnouncement && <FeaturedAnnouncementCard announcement={featuredAnnouncement} />}
        
        {/* Announcements grid */}
        {filteredAnnouncements.length > 0 ? (
          <>
            {viewType === VIEW_TYPES.GRID && (
              <motion.div 
                className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 stagger-fade-in"
              >
                {filteredAnnouncements.map(announcement => (
                  <AnnouncementCard key={announcement.id} announcement={announcement} />
                ))}
              </motion.div>
            )}
            
            {viewType === VIEW_TYPES.LIST && (
              <motion.div 
                className="flex flex-col space-y-4"
              >
                {filteredAnnouncements.map(announcement => (
                  <AnnouncementListItem key={announcement.id} announcement={announcement} />
                ))}
              </motion.div>
            )}
            
            {viewType === VIEW_TYPES.TIMELINE && (
              <div className="timeline-container mt-8 pt-8">
                <div className="timeline-line"></div>
                {filteredAnnouncements.map((announcement, index) => (
                  <TimelineItem 
                    key={announcement.id} 
                    announcement={announcement}
                    index={index}
                  />
                ))}
              </div>
            )}
          </>
        ) : (
          <EmptyState />
        )}
      </main>
      
      {/* Footer */}
      <footer className="modern-footer py-8 mt-auto">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="footer-content">
            <a href="/voltaris/" className="footer-logo">
              <img 
                src={`${process.env.PUBLIC_URL}/logo_kırmızı.png`}
                alt="Voltaris Logo"
                className="h-10 w-auto"
              />
            </a>
            <div className="space-y-1 text-right">
              <div className="text-gray-500 text-sm">
                © 2025 Voltaris Elektromobil Takımı
              </div>
              <div className="text-gray-400 text-xs">
                IYTE Elektrikli Araç Geliştirme Ekibi
              </div>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default ModernDuyurularPage;